import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";
import { Icon } from "./icon";
import { menuStyles } from "./dropdown-menu";

const styles = stylex.create({
  root: {
    position: "relative",
    display: "inline-block",
    minWidth: 180,
    backgroundColor: raster.paper,
  },
});

export interface SelectOption {
  value: string;
  label: React.ReactNode;
}

export interface SelectProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  placeholder?: React.ReactNode;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
}

/** Listbox on a hairline trigger; the open menu overlays. */
export function Select({
  options,
  value,
  defaultValue,
  placeholder = "Select…",
  onValueChange,
  disabled,
  className,
  style,
  ...props
}: SelectProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const selectedIndex = options.findIndex((o) => o.value === current);
  const [activeIndex, setActiveIndex] = React.useState(Math.max(0, selectedIndex));

  const select = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
    setOpen(false);
    triggerRef.current?.focus();
  };

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const onTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key) && !open) {
      e.preventDefault();
      setActiveIndex(Math.max(0, selectedIndex));
      setOpen(true);
      return;
    }
    if (!open) return;
    if (e.key === "Escape") setOpen(false);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(options.length - 1, i + 1));
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    }
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const active = options[activeIndex];
      if (active) select(active.value);
    }
  };

  const selected = selectedIndex >= 0 ? options[selectedIndex] : undefined;
  const root = rs(["rs-select", className], menuStyles.select, styles.root);
  const trigger = rs(["rs-dropdown"], menuStyles.dropdown);
  const menu = rs(["rs-menu"], menuStyles.menu, menuStyles.menuOverlay);

  return (
    <div ref={rootRef} className={root.className} style={{ ...root.style, ...style }} {...props}>
      <button
        ref={triggerRef}
        type="button"
        className={trigger.className}
        style={trigger.style}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${idBase}-listbox`}
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={onTriggerKeyDown}
      >
        <span>{selected ? selected.label : placeholder}</span>
        <Icon name="chevron-right" rotate={90} />
      </button>
      {open && (
        <div
          id={`${idBase}-listbox`}
          role="listbox"
          className={menu.className}
          style={menu.style}
          aria-activedescendant={`${idBase}-opt-${activeIndex}`}
        >
          {options.map((option, index) => {
            const active = option.value === current || index === activeIndex;
            const row = rs(
              ["rs-menu-item", active && "rs-menu-item-active"],
              menuStyles.item,
              active && menuStyles.itemActive,
            );
            return (
              <button
                key={option.value}
                id={`${idBase}-opt-${index}`}
                type="button"
                role="option"
                aria-selected={option.value === current}
                className={row.className}
                style={row.style}
                onPointerEnter={() => setActiveIndex(index)}
                onClick={() => select(option.value)}
              >
                {option.label}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";
import {
  iconGroups,
  iconLabel,
  iconNames,
  marks,
  resolveIcon,
  type IconName,
  type IconRotate,
  type MarkEl,
} from "./icon-marks";

const at480 = "@media (max-width: 480px)" as const;

export { iconGroups, iconLabel, iconNames, resolveIcon };
export type { IconName, IconRotate };
export type { DrawnName, IconAlias, IconGroup } from "./icon-marks";

/**
 * Raster chrome marks. Vera 28 Aug 2026; optical recut 1 Sep 2026; R1 pairs 1 Sep 2026.
 *
 * 16×16 module, optical center 8,8. Line: stroke 1, fill none.
 * Filled: same figures, solid closed geometry, currentColor. Not a second library.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12, 16, and 24.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 * First five marks (copy, copied, chevron-left, chevron-right, close) stay as drawn,
 * except L/R chevrons take a measured +0.25y optical nudge toward 8,8.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export const iconFill = {
  fill: "currentColor",
  stroke: "none",
} as const;

export type IconSize = 12 | 16 | 24;
export type IconVariant = "line" | "filled";

const styles = stylex.create({
  icon: {
    display: "block",
    flexShrink: 0,
    overflow: "visible",
    color: "inherit",
  },
  row: {
    display: "flex",
    gap: 18,
    alignItems: "center",
    color: raster.ink,
  },
  catalog: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: 28,
    textAlign: "left",
    alignSelf: "stretch",
  },
  group: {
    display: "flex",
    flexDirection: "column",
    gap: 12,
  },
  groupTitle: {
    margin: 0,
    fontSize: 12,
    fontWeight: 600,
    letterSpacing: 0,
    color: raster.gray,
    textTransform: "none",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: {
      default: "repeat(auto-fill, 184px)",
      [at480]: "minmax(0, 1fr)",
    },
    columnGap: raster.gutter,
    rowGap: 20,
    justifyContent: "start",
    width: "100%",
  },
  cell: {
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
    gap: 8,
    width: {
      default: 184,
      [at480]: "100%",
    },
  },
  pair: {
    display: "flex",
    alignItems: "center",
    gap: 16,
    minHeight: 24,
  },
  kin: {
    display: "flex",
    alignItems: "center",
    gap: 8,
    minHeight: 24,
  },
  label: {
    fontSize: 11,
    lineHeight: 1.3,
    color: raster.gray,
    textTransform: "none",
  },
});

function isClosed(el: MarkEl): boolean {
  if (el.t === "rect" || el.t === "circle") return true;
  if (el.t === "path") return /z\s*$/i.test(el.d.trim());
  return false;
}

function inkFor(el: MarkEl, variant: IconVariant) {
  return variant === "filled" && isClosed(el) ? iconFill : iconInk;
}

function renderEl(el: MarkEl, key: number, variant: IconVariant): React.ReactNode {
  const ink = inkFor(el, variant);
  switch (el.t) {
    case "path":
      return <path key={key} d={el.d} {...ink} />;
    case "rect":
      return <rect key={key} x={el.x} y={el.y} width={el.w} height={el.h} {...ink} />;
    case "circle":
      return <circle key={key} cx={el.cx} cy={el.cy} r={el.r} {...ink} />;
    case "line":
      return <line key={key} x1={el.x1} y1={el.y1} x2={el.x2} y2={el.y2} {...ink} />;
  }
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Line hairline, or filled kinship of the same figure. */
  variant?: IconVariant;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, variant = "line", rotate, className, style, ...props }: IconProps) {
  const resolved = resolveIcon(name);
  const turn = rotate ?? resolved.rotate;
  const nodes = marks[resolved.mark].map((el, i) => renderEl(el, i, variant));
  const sx = rs(["rs-icon", variant === "filled" && "rs-icon-filled", className], styles.icon);
  return (
    <svg
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
      className={sx.className}
      style={{ ...sx.style, ...style }}
    >
      {turn ? <g transform={`rotate(${turn} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Inline mark row. One family, current color. */
export function Icons({ className, style, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const sx = rs(["rs-icons", className], styles.row);
  return <div {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

/** Full family at 12, 16, and 24, line | filled, grouped. Optical center 8,8. */
export function IconCatalog({ className }: { className?: string }) {
  const catalog = rs(["rs-icon-catalog", className], styles.catalog);
  const group = rs(["rs-icon-group"], styles.group);
  const groupTitle = rs(["rs-icon-group-title"], styles.groupTitle);
  const grid = rs(["rs-icon-grid"], styles.grid);
  const cell = rs(["rs-icon-cell"], styles.cell);
  const pair = rs(["rs-icon-pair"], styles.pair);
  const kin = rs(["rs-icon-kin"], styles.kin);
  const label = rs(["rs-icon-label"], styles.label);
  return (
    <div className={catalog.className} style={catalog.style}>
      {iconGroups.map((g) => (
        <section
          key={g.title}
          id={g.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}
          className={group.className}
          style={group.style}
        >
          <h3 className={groupTitle.className} style={groupTitle.style}>
            {g.title}
          </h3>
          <div className={grid.className} style={grid.style}>
            {g.names.map((mark) => (
              <div key={`${g.title}-${mark}`} className={cell.className} style={cell.style}>
                <div className={pair.className} style={pair.style}>
                  <div className={kin.className} style={kin.style} data-variant="line">
                    <Icon name={mark} size={12} />
                    <Icon name={mark} size={16} />
                    <Icon name={mark} size={24} />
                  </div>
                  <div className={kin.className} style={kin.style} data-variant="filled">
                    <Icon name={mark} size={12} variant="filled" />
                    <Icon name={mark} size={16} variant="filled" />
                    <Icon name={mark} size={24} variant="filled" />
                  </div>
                </div>
                <span className={label.className} style={label.style}>
                  {iconLabel(mark)}
                </span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, phone as phoneMq } from "./tokens.stylex";
import { rs } from "./rs";

/** StyleX cannot read a string const from a defineVars file; keep the token import. */
const phone = "@media (max-width: 640px)" as typeof phoneMq;
import { Icon } from "./icon";

export interface DropdownMenuItem {
  label?: React.ReactNode;
  onSelect?: () => void;
  disabled?: boolean;
  separator?: boolean;
}

export interface DropdownMenuProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  items: DropdownMenuItem[];
}

export const menuStyles = stylex.create({
  select: {
    position: "relative",
    display: {
      default: "inline-block",
      [phone]: "block",
    },
    minWidth: {
      default: 180,
      [phone]: 0,
    },
    width: {
      default: null,
      [phone]: "100%",
    },
  },
  dropdown: {
    boxSizing: "border-box",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 12,
    paddingBlock: {
      default: 9,
      [phone]: 12,
    },
    paddingInline: {
      default: 12,
      [phone]: 14,
    },
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: {
      default: raster.radiusSm,
      [phone]: 0,
    },
    fontSize: {
      default: 14,
      [phone]: raster.controlFs,
    },
    color: raster.ink,
    letterSpacing: "-0.01em",
    cursor: "pointer",
    fontFamily: "inherit",
    backgroundColor: "transparent",
    width: "100%",
    minHeight: {
      default: null,
      [phone]: raster.hit,
    },
  },
  menu: {
    boxSizing: "border-box",
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: {
      default: raster.radiusSm,
      [phone]: 0,
    },
    marginTop: {
      default: 6,
      [phone]: 0,
    },
    overflow: "hidden",
    backgroundColor: raster.paper,
    boxShadow: {
      default: "0 8px 24px rgba(0,0,0,0.06)",
      [phone]: "none",
    },
  },
  menuOverlay: {
    position: "absolute",
    top: "100%",
    left: 0,
    right: 0,
    zIndex: 50,
  },
  menuFixed: {
    position: "fixed",
    zIndex: 220,
    marginTop: 0,
    minWidth: 160,
  },
  menuCal: {
    right: "auto",
    padding: 12,
  },
  menuCombobox: {
    position: "absolute",
    top: "100%",
    left: 0,
    right: 0,
    zIndex: 50,
    maxHeight: 240,
    overflowY: "auto",
  },
  item: {
    boxSizing: "border-box",
    display: {
      default: "block",
      [phone]: "flex",
    },
    alignItems: {
      default: null,
      [phone]: "center",
    },
    paddingBlock: {
      default: 9,
      [phone]: 12,
    },
    paddingInline: {
      default: 12,
      [phone]: 14,
    },
    fontSize: {
      default: 14,
      [phone]: raster.controlFs,
    },
    color: raster.ink,
    letterSpacing: "-0.01em",
    borderBottomWidth: {
      default: raster.hairline,
      ":last-child": 0,
    },
    borderBottomStyle: "solid",
    borderBottomColor: raster.divider,
    borderLeftWidth: 0,
    borderRightWidth: 0,
    borderTopWidth: 0,
    width: "100%",
    textAlign: "left",
    cursor: "pointer",
    backgroundColor: "transparent",
    fontFamily: "inherit",
    minHeight: {
      default: null,
      [phone]: raster.hit,
    },
  },
  itemActive: {
    backgroundColor: raster.dividerSubtle,
  },
  sep: {
    borderWidth: 0,
    borderTopWidth: raster.hairline,
    borderTopStyle: "solid",
    borderTopColor: raster.divider,
    marginBlock: 4,
    marginInline: 0,
  },
});

/** Action menu with menu semantics and keyboard navigation. */
export function DropdownMenu({ label, items, className, style, ...props }: DropdownMenuProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const actionable = items.filter((item) => !item.separator);
  const [activeIndex, setActiveIndex] = React.useState(0);

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const select = (item: DropdownMenuItem) => {
    if (item.disabled) return;
    setOpen(false);
    triggerRef.current?.focus();
    item.onSelect?.();
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!open) {
      if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key)) {
        e.preventDefault();
        setActiveIndex(0);
        setOpen(true);
      }
      return;
    }
    if (e.key === "Escape") {
      setOpen(false);
      triggerRef.current?.focus();
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(actionable.length - 1, i + 1));
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    }
    if (e.key === "Home") setActiveIndex(0);
    if (e.key === "End") setActiveIndex(actionable.length - 1);
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const item = actionable[activeIndex];
      if (item) select(item);
    }
  };

  let actionIndex = -1;
  const root = rs(["rs-select", className], menuStyles.select);
  const trigger = rs(["rs-dropdown"], menuStyles.dropdown);
  const menu = rs(["rs-menu"], menuStyles.menu, menuStyles.menuOverlay);
  return (
    <div
      ref={rootRef}
      className={root.className}
      style={{ ...root.style, ...style }}
      onKeyDown={onKeyDown}
      {...props}
    >
      <button
        ref={triggerRef}
        type="button"
        className={trigger.className}
        style={trigger.style}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={`${idBase}-menu`}
        onClick={() => setOpen((o) => !o)}
      >
        <span>{label}</span>
        <Icon name="chevron-right" rotate={90} />
      </button>
      {open && (
        <div id={`${idBase}-menu`} role="menu" className={menu.className} style={menu.style}>
          {items.map((item, index) => {
            if (item.separator) {
              const sep = rs(["rs-menu-sep"], menuStyles.sep);
              return <hr key={`sep-${index}`} className={sep.className} style={sep.style} />;
            }
            actionIndex++;
            const current = actionIndex;
            const row = rs(
              ["rs-menu-item", current === activeIndex && "rs-menu-item-active"],
              menuStyles.item,
              current === activeIndex && menuStyles.itemActive,
            );
            return (
              <button
                key={index}
                type="button"
                role="menuitem"
                disabled={item.disabled}
                className={row.className}
                style={row.style}
                onPointerEnter={() => setActiveIndex(current)}
                onClick={() => select(item)}
              >
                {item.label}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
